import raw from "@/data/environment/jezero/meda_jezero_sample.json";
import type {
  DatasetAvailability,
  EnvironmentalSeries,
  JezeroEnvironmentalDataset,
  SolSummary,
} from "./types";

/**
 * Committed, build-time dataset generated by
 * `team/environment/jezero/build_dataset.py` from checked PDS4 products.
 *
 * The JSON is imported statically so the panel works offline and cannot show a
 * partially loaded or silently substituted dataset. Nothing here fetches at
 * runtime.
 */
const dataset = raw as unknown as JezeroEnvironmentalDataset;

export const jezeroEnvironmentalDataset: JezeroEnvironmentalDataset = dataset;

export function solNumbers(input: JezeroEnvironmentalDataset = dataset): number[] {
  return input.sols.map((entry) => entry.sol);
}

export function solSummary(
  sol: number,
  input: JezeroEnvironmentalDataset = dataset,
): SolSummary | null {
  return input.sols.find((entry) => entry.sol === sol) ?? null;
}

export function seriesForSol(
  sol: number,
  input: JezeroEnvironmentalDataset = dataset,
): EnvironmentalSeries[] {
  return input.series.filter((series) => series.sol === sol);
}

export function seriesById(
  id: string,
  input: JezeroEnvironmentalDataset = dataset,
): EnvironmentalSeries | null {
  return input.series.find((series) => series.id === id) ?? null;
}

/** All series for one quantity on one sol, in dataset order. */
export function seriesForQuantity(
  quantity: string,
  sol: number,
  input: JezeroEnvironmentalDataset = dataset,
): EnvironmentalSeries[] {
  return seriesForSol(sol, input).filter(
    (series) => series.physicalQuantity === quantity,
  );
}

export function availabilityFor(
  quantity: string,
  input: JezeroEnvironmentalDataset = dataset,
): DatasetAvailability | null {
  return input.availability.find((entry) => entry.quantity === quantity) ?? null;
}

/**
 * Structural checks that must hold for every committed dataset. These are the
 * same invariants the tests assert, so a bad regeneration fails loudly instead
 * of rendering a plausible-looking but wrong panel.
 */
export function validateDataset(
  input: JezeroEnvironmentalDataset = dataset,
): { ok: boolean; problems: string[] } {
  const problems: string[] = [];
  const allowedSols = new Set(input.displayWindow.solSelection);

  if (input.regionId !== "jezero") problems.push("dataset regionId is not jezero");
  if (input.instrument !== "MEDA") problems.push("dataset instrument is not MEDA");
  if (input.aggregation.interpolated) {
    problems.push("dataset aggregation is marked as interpolated");
  }

  for (const entry of input.sols) {
    if (!allowedSols.has(entry.sol)) {
      problems.push(`sol ${entry.sol} is outside the declared sample window`);
    }
  }

  for (const series of input.series) {
    const label = series.id;
    if (series.regionId !== "jezero") problems.push(`${label}: regionId is not jezero`);
    if (series.sol !== Number(label.split("-")[2])) {
      problems.push(`${label}: sol does not match series id`);
    }
    if (!series.unit) problems.push(`${label}: missing unit`);
    if (series.aggregation.interpolated) {
      problems.push(`${label}: series aggregation is marked as interpolated`);
    }
    if (series.aggregation.minimumNativeSamplesPerBin < 1) {
      problems.push(`${label}: invalid minimum sample count per bin`);
    }
    let lastT = -1;
    let native = 0;
    for (const point of series.points) {
      if (point.t < 0 || point.t >= 86_400) problems.push(`${label}: point time out of sol`);
      if (point.t <= lastT) problems.push(`${label}: points are not strictly ordered`);
      if (point.n < 1) problems.push(`${label}: bin without native samples`);
      if (point.v === null) problems.push(`${label}: null bin mean was emitted`);
      if (point.v === 999_999_999) problems.push(`${label}: sentinel leaked into value`);
      lastT = point.t;
      native += point.n;
    }
    if (native !== series.summary.validSamples) {
      problems.push(`${label}: summary sample count does not match bins`);
    }
  }

  return { ok: problems.length === 0, problems };
}
